import{_ as t,o as i,c as s,aF as a}from"./chunks/framework.DLvxyDDa.js";const n="/service-ekosystem/assets/k2-3D-tiles.D7K6XRb5.png",l="/service-ekosystem/assets/k2-elevation.BKRHORiu.png",u=JSON.parse('{"title":"service-k2","description":"3D terrain server for Cesium tiles","frontmatter":{"title":"service-k2","description":"3D terrain server for Cesium tiles"},"headers":[],"relativePath":"packages/service-k2/index.md","filePath":"packages/service-k2/index.md"}'),r={name:"packages/service-k2/index.md"};function o(d,e,h,p,c,k){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="service-k2" tabindex="-1">service-k2 <a class="header-anchor" href="#service-k2" aria-label="Permalink to &quot;service-k2&quot;">​</a></h1><p><em>3D terrain server for Cesium tiles</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><strong>service-k2</strong> is a lightweight service that exposes different endpoints related to terrain data:</p><ul><li>a <strong>3D terrain tiles</strong> endpoint that lets you access quantized meshes stored in MBTiles for <a href="https://cesium.com/" target="_blank" rel="noreferrer">Cesium</a>,</li><li>an <strong>elevation</strong> endpoint that lets you compute the elevation of the terrain under a linear geographical element.</li></ul><p><img src="'+n+'" alt="3D Tiles"></p><p><img src="'+l+'" alt="Elevation computation"></p><p>For 3D terrain tiles, the service always serves a single terrain file on the root path (<code>/</code>), taken from the <code>TERRAIN_FILEPATH</code> environment variable (default <code>/mbtiles/terrain.mbtiles</code>). In addition, if the <code>TERRAIN_FOLDER</code> environment variable is set, every <code>*.mbtiles</code> file found in that folder is also served, each under a path derived from its basename.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Serving the single <code>TERRAIN_FILEPATH</code> file is always active, even when <code>TERRAIN_FOLDER</code> is set. That file must therefore exist, otherwise the service fails to start.</p></div><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><p><strong>service-k2</strong> needs data to serve, and its two features rely on <strong>different datasets</strong> — so to run the service locally (or in production) you have to provide the data for whichever feature you want to use:</p><ul><li><p><strong>3D terrain tiles</strong> are served from <strong>quantized-mesh <code>.mbtiles</code></strong> files, configured through <code>TERRAIN_FILEPATH</code> or <code>TERRAIN_FOLDER</code> (see <a href="#configuration">Configuration</a>). See <a href="#converting-geotiff-to-mbtiles">Converting GeoTIFF to MBTiles</a> to produce them.</p></li><li><p><strong>Elevation computation</strong> reads a <strong>Digital Elevation Model (DEM/MNT)</strong> in a GDAL-readable format (GeoTIFF or VRT). By default the DEM is picked from <code>/mbtiles</code> depending on the requested resolution:</p><table tabindex="0"><thead><tr><th>Resolution</th><th>DEM file</th></tr></thead><tbody><tr><td><code>&lt; 250 m</code></td><td><code>/mbtiles/srtm.vrt</code></td></tr><tr><td><code>&lt; 500 m</code></td><td><code>/mbtiles/GMTED2010/mx75.tif</code></td></tr><tr><td><code>&lt; 1000 m</code></td><td><code>/mbtiles/GMTED2010/mx15.tif</code></td></tr><tr><td>otherwise</td><td><code>/mbtiles/GMTED2010/mx30.tif</code></td></tr></tbody></table><p>You can bypass this selection with the <code>demOverride</code> parameter, resolved relative to <code>/mbtiles</code>. Note that this <code>/mbtiles</code> root is <strong>not</strong> configurable through an environment variable. The <code>/elevation</code> endpoint also requires <strong>GDAL</strong> (<code>gdalwarp</code>) to be installed on the host or image at runtime.</p></li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Install with your preferred package manager:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-6Cz-J" id="tab-HRClUrK" checked><label data-title="pnpm" for="tab-HRClUrK">pnpm</label><input type="radio" name="group-6Cz-J" id="tab-cuX8PRd"><label data-title="npm" for="tab-cuX8PRd">npm</label><input type="radio" name="group-6Cz-J" id="tab-Im6GkvK"><label data-title="yarn" for="tab-Im6GkvK">yarn</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/service-k2</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/service-k2</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/service-k2</span></span></code></pre></div></div></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Here are the environment variables you can use to customize the service:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Defaults</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>The port to be used when exposing the service</td><td><code>8080</code></td></tr><tr><td><code>BODY_LIMIT</code></td><td>The size limit of the request body</td><td><code>100kb</code></td></tr><tr><td><code>TERRAIN_FILEPATH</code></td><td>Path to a single terrain <code>.mbtiles</code> file (single-file mode)</td><td><code>/mbtiles/terrain.mbtiles</code></td></tr><tr><td><code>TERRAIN_FOLDER</code></td><td>Path to a folder of <code>*.mbtiles</code> terrain files (multi-file mode)</td><td>-</td></tr></tbody></table><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>The HTTP API exposed by <strong>service-k2</strong> is documented on the <a href="./service-k2-openapi.html">API reference</a> page.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>The test suite uses <a href="https://vitest.dev/" target="_blank" rel="noreferrer">Vitest</a> and exercises the elevation computation against a bundled DEM through GDAL. It is skipped automatically when GDAL is not installed.</p><p>To run the tests, use the <code>test</code> script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><h2 id="converting-geotiff-to-mbtiles" tabindex="-1">Converting GeoTIFF to MBTiles <a class="header-anchor" href="#converting-geotiff-to-mbtiles" aria-label="Permalink to &quot;Converting GeoTIFF to MBTiles&quot;">​</a></h2><ol><li>Run a <a href="https://github.com/tum-gis/cesium-terrain-builder-docker" target="_blank" rel="noreferrer">cesium-terrain-builder-docker</a> container with a volume mounted on the folder with your GeoTIFF files:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ctb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;./path/to/geotiff/:/data&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tumgis/ctb-quantized-mesh</span></span></code></pre></div><ol start="2"><li>Build a virtual dataset with all of the GeoTIFF files:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdalbuildvrt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset.vrt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tif</span></span></code></pre></div><ol start="3"><li>Reproject data to EPSG:4326:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdalwarp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s_srs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPSG:2154</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t_srs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPSG:4326</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset.vrt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset-EPSG4326.vrt</span></span></code></pre></div><ol start="4"><li>Build overview images:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdaladdo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> average</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset-EPSG4326.vrt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span></span></code></pre></div><ol start="5"><li>Generate quantized meshes with <a href="https://github.com/tum-gis/cesium-terrain-builder-docker?tab=readme-ov-file#create-cesium-terrain-files" target="_blank" rel="noreferrer">cesium-terrain-builder-docker</a>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctb-tile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Mesh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /target/path/for/generated/quantized/meshes/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset-EPSG4326.vrt</span></span></code></pre></div><ol start="6"><li>Generate <code>layer.json</code>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctb-tile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Mesh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /target/path/for/generated/quantized/meshes/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset-EPSG4326.vrt</span></span></code></pre></div><ol start="7"><li>Outside of the container, get the <a href="https://github.com/kalisio/service-ekosystem/blob/master/packages/service-k2/tools/quantized_mesh2mbtiles.py" target="_blank" rel="noreferrer"><code>quantized_mesh2mbtiles.py</code></a> script from this project, and generate the MBTiles file from the quantized meshes:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quantized_mesh2mbtiles.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/quantized/meshes/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> terrain.mbtiles</span></span></code></pre></div>',39)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
